# owner: platform
"""Short absence notices for parents."""

from typing import Iterable, List

from rosterkit.models import Mark, Student


def _absent_days(student: Student, marks: List[Mark]) -> list:
    if any(mark.student_id != student.student_id for mark in marks):
        raise ValueError("marks belong to a different student")
    return sorted(mark.day for mark in marks if mark.status == "absent")


# ---
def absence_notice(student: Student, marks: Iterable[Mark]) -> str:
    days = _absent_days(student, list(marks))
    if not days:
        raise ValueError("no absences to report")
    name = f"{student.first_name} {student.last_name}"
    dates = ", ".join(day.isoformat() for day in days)
    return f"{name} missed {len(days)} day(s) of school: {dates}."

