# owner: platform
import unittest
from rosterkit.notices import absence_notice
from rosterkit.models import Mark, Student
from datetime import date

PUPIL = Student("s1", "Smith", "Ana", "A")


def _mark(number, status="absent", owner="s1"):
    return Mark(owner, date(2026, 9, number), status)


class NoticeTests(unittest.TestCase):
    def test_lists_absences_in_order(self):
        marks = [_mark(9), _mark(4, "present"), _mark(2)]
        text = absence_notice(PUPIL, marks)
        self.assertEqual(
            text, "Ana Smith missed 2 day(s) of school: 2026-09-02, 2026-09-09."
        )

    def test_other_student(self):
        with self.assertRaises(ValueError):
            absence_notice(PUPIL, [_mark(2), _mark(3, owner="s2")])

    def test_no_absences(self):
        with self.assertRaises(ValueError):
            absence_notice(PUPIL, [_mark(2, "late")])


if __name__ == "__main__":
    unittest.main()
